package cn.balltv.portal;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import org.json.*;
public class EventOrderTest {
 Events.Group group(String id,String league,String home,String time,String state)throws Exception{Feeds.Match m=new Feeds.Match();m.source="咖啡";m.id=id;m.title=home+" VS 客队";m.home=home;m.away="客队";m.league=league;m.time=time;m.status=state;m.sport=league.contains("NBA")||league.contains("CBA")?"2":"1";m.raw=new JSONObject();return Events.group(Arrays.asList(m),false).get(0);}
 final Set<String> empty=Collections.emptySet();
 @Test public void importantLeagueOutranksManyMirrorsOfMinorMatch()throws Exception{Events.Group nba=group("nba","NBA","湖人","2026-11-09 10:00","live"),minor=group("minor","业余杯","甲队","2026-11-09 09:00","live");for(int i=0;i<8;i++){Feeds.Match m=new Feeds.Match();m.source="镜像"+i;minor.members.add(m);}ArrayList<Events.Group> rows=new ArrayList<Events.Group>(Arrays.asList(minor,nba));EventOrder.sort(rows,"live","recommended",empty);assertEquals(nba,rows.get(0));assertTrue(EventOrder.reason(nba,empty).contains("NBA"));}
 @Test public void chinaAndFavoritesGetExplicitReasons()throws Exception{Events.Group china=group("cn","友谊赛","中国女足","2026-11-09 20:00","live");assertTrue(EventOrder.priority(china,empty)>=100);assertEquals("中国球队 · 重点关注",EventOrder.reason(china,empty));assertEquals("你的收藏",EventOrder.reason(china,Collections.singleton(china.id)));}
 @Test public void titleOnlyHypeCannotPromoteUnknownRoom()throws Exception{Events.Group g=group("hype","NBA","甲","","live");g.lead().estimated=true;g.lead().title="NBA 世界杯 重点直播";assertEquals(0,EventOrder.priority(g,empty));assertEquals("",EventOrder.reason(g,empty));}
 @Test public void upcomingBigEventDoesNotJumpAheadOfLiveMatch()throws Exception{Events.Group next=group("nba","NBA","湖人","2026-11-10 10:00","upcoming"),live=group("small","业余杯","甲","2026-11-09 20:00","live");ArrayList<Events.Group> rows=new ArrayList<Events.Group>(Arrays.asList(next,live));EventOrder.sort(rows,"live","recommended",empty);assertEquals(live,rows.get(0));}
 @Test public void womensLeaguesAreNotMisidentifiedAsMensLeagues()throws Exception{assertEquals("WNBA",EventOrder.league(group("w","WNBA","甲","2026-11-09 10:00","live")));assertEquals("WCBA",EventOrder.league(group("c","WCBA","甲","2026-11-09 10:00","live")));assertEquals("NCAA",EventOrder.league(group("n","NCAA","甲","2026-11-09 10:00","live")));}
 @Test public void scheduleTimeOrderIgnoresPopularityAndPutsUnknownTimeLast()throws Exception{Events.Group early=group("a","低级别联赛","甲","2026-11-09 08:00","live"),late=group("b","NBA","乙","2026-11-09 10:00","live"),unknown=group("x","NBA","丙","","live");ArrayList<Events.Group> rows=new ArrayList<Events.Group>(Arrays.asList(unknown,late,early));EventOrder.sort(rows,"schedule","time",empty);assertEquals(Arrays.asList(early,late,unknown),rows);}
 @Test public void leagueScheduleStillKeepsDatesInChronologicalOrder()throws Exception{Events.Group first=group("a","业余杯","甲","2026-11-09 20:00","upcoming"),next=group("b","NBA","乙","2026-11-10 08:00","upcoming"),nba=group("c","NBA","丙","2026-11-09 21:00","upcoming");ArrayList<Events.Group> rows=new ArrayList<Events.Group>(Arrays.asList(next,first,nba));EventOrder.sort(rows,"schedule","league",empty);assertEquals(Arrays.asList(nba,first,next),rows);}
 @Test public void chineseDayLabelsDoNotUseDeviceTimezone(){TimeZone before=TimeZone.getDefault();try{TimeZone.setDefault(TimeZone.getTimeZone("America/Los_Angeles"));long now=Events.epoch("2026-11-09 23:30");assertEquals("2026-11-10",EventOrder.dayKey(Events.epoch("2026-11-09T16:30:00Z")));assertTrue(EventOrder.dayLabel(Events.epoch("2026-11-10 08:00"),now).startsWith("明天"));assertEquals("08:00",EventOrder.time(Events.epoch("2026-11-10 08:00")));assertEquals("待定",EventOrder.time(0));}finally{TimeZone.setDefault(before);}}
 @Test public void historyKeepsEncounterOrder()throws Exception{Events.Group a=group("a","业余杯","甲","2026-11-09 20:00","live"),b=group("b","NBA","乙","2026-11-09 08:00","live");ArrayList<Events.Group> rows=new ArrayList<Events.Group>(Arrays.asList(a,b));EventOrder.sort(rows,"history","recommended",empty);assertEquals(a,rows.get(0));}
 @Test public void structuredFixtureCanBeRankedWhenOnlyLiveStateIsInferred()throws Exception{Events.Group g=group("jr","NBA","湖人","2026-11-09 10:00","live");g.lead().estimated=true;assertTrue(EventOrder.priority(g,empty)>100);}
 @Test public void youthAndQualifierCupNamesAreNotCollapsedIntoSeniorFinals()throws Exception{Events.Group youth=group("y","U17世界杯","甲","2026-11-09 20:00","live"),nba=group("nba","NBA","乙","2026-11-09 20:00","live"),qualifier=group("q","世界杯预选赛","丙","2026-11-09 20:00","live");assertEquals("U17世界杯",EventOrder.league(youth));assertEquals("世界杯预选赛",EventOrder.league(qualifier));assertTrue(EventOrder.priority(youth,empty)<EventOrder.priority(nba,empty));assertTrue(EventOrder.priority(qualifier,empty)<EventOrder.priority(nba,empty));}
}
